function match(pattern: string, path: string): Record<string, string> | undefined {
  const segments = pattern.split("/").filter(Boolean);
  const parts = path.split("/").filter(Boolean);
  if (segments.length !== parts.length) return undefined;
  const params: Record<string, string> = {};
  for (const [i, segment] of segments.entries()) {
    if (segment.startsWith(":")) params[segment.slice(1)] = decodeURIComponent(parts[i]!);
    else if (segment !== parts[i]) return undefined;
  }
  return params;
}

