const routes = [
  { method: "GET", pattern: "/books", name: "list" },
  { method: "POST", pattern: "/books", name: "create" },
  { method: "GET", pattern: "/books/:id", name: "show" },
];

function matchRoute(list: typeof routes, method: string, path: string): string {
  const parts = path.split("/").filter(Boolean);
  const allowed: string[] = [];
  for (const route of list) {
    const segments = route.pattern.split("/").filter(Boolean);
    if (segments.length !== parts.length) continue;
    const params: Record<string, string> = {};
    const fits = segments.every((segment, i) => {
      if (segment.startsWith(":")) {
        params[segment.slice(1)] = parts[i]!;
        return true;
      }
      return segment === parts[i];
    });
    if (!fits) continue;
    if (route.method === method) return `${route.name} ${JSON.stringify(params)}`;
    allowed.push(route.method);
  }
  return allowed.length > 0 ? `405 ${allowed.join(",")}` : "404";
}

