type Ctx = { log: string[] };
type Mw = (ctx: Ctx, next: () => Promise<number>) => Promise<number>;

function compose(middleware: Mw[], handler: (ctx: Ctx) => Promise<number>) {
  return (ctx: Ctx): Promise<number> => {
    let last = -1;
    const run = async (index: number): Promise<number> => {
      if (index <= last) throw new Error("next() called twice");
      last = index;
      const current = middleware[index];
      return current ? current(ctx, () => run(index + 1)) : handler(ctx);
    };
    return run(0);
  };
}

