function withBody<T>(parse: (input: unknown) => Parsed<T>, handler: (ctx: Ctx, value: T) => Response) {
  return (ctx: Ctx): Response => {
    const result = parse(ctx.body);
    if (!result.ok) return { status: 400, body: { error: "validation_failed", issues: result.issues } };
    return handler(ctx, result.value);
  };
}

