function parseBody(text: string, contentType: string, limit: number): { status: number; value?: unknown } {
  if (text.length > limit) return { status: 413 };
  if (!contentType.startsWith("application/json")) return { status: 415 };
  try {
    return { status: 200, value: JSON.parse(text) };
  } catch {
    return { status: 400 };
  }
}

